CREATE TABLE config (guild_id TEXT PRIMARY KEY, body TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE actions (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, actor TEXT NOT NULL, target TEXT, kind TEXT NOT NULL, state TEXT NOT NULL, details TEXT NOT NULL, created_at INTEGER NOT NULL, error TEXT);
CREATE TABLE staff (guild_id TEXT NOT NULL, user_id TEXT NOT NULL, rank TEXT, status TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(guild_id,user_id));
CREATE TABLE staff_history (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, actor TEXT NOT NULL, kind TEXT NOT NULL, old_rank TEXT, new_rank TEXT, reason TEXT NOT NULL, note TEXT, created_at INTEGER NOT NULL);
CREATE TABLE sanctions (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, actor TEXT NOT NULL, kind TEXT NOT NULL, reason TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, expires_at INTEGER, token TEXT, state TEXT NOT NULL DEFAULT 'applied');
CREATE INDEX sanction_due ON sanctions(kind,active,expires_at);
CREATE TABLE staff_warnings (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER, revoked_by TEXT);
CREATE TABLE logs (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, category TEXT NOT NULL, actor TEXT, target TEXT, action TEXT NOT NULL, reason TEXT, result TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE hits (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, actor TEXT NOT NULL, rule TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX hit_window ON hits(guild_id,actor,rule,created_at);
CREATE TABLE audit_seen (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE incidents (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, actor TEXT, rule TEXT NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE outbox (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', message_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL, created_at INTEGER NOT NULL, error TEXT);
CREATE INDEX outbox_due ON outbox(state,next_at);
CREATE TABLE changelogs (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, actor TEXT NOT NULL, pages TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE giveaways (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, message_id TEXT, actor TEXT NOT NULL, prize TEXT NOT NULL, conditions TEXT NOT NULL, winner_count INTEGER NOT NULL, ends_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'active', seed TEXT NOT NULL, commitment TEXT NOT NULL, round INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE giveaway_entries (giveaway_id TEXT NOT NULL REFERENCES giveaways(id), user_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(giveaway_id,user_id));
CREATE TABLE giveaway_draws (giveaway_id TEXT NOT NULL REFERENCES giveaways(id), round INTEGER NOT NULL, seed TEXT NOT NULL, commitment TEXT NOT NULL, entrants TEXT NOT NULL, winners TEXT NOT NULL, excluded TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(giveaway_id,round));
CREATE TABLE documents (id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, kind TEXT NOT NULL, version INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, actor TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(guild_id,kind,version));
CREATE TABLE acceptances (document_id INTEGER NOT NULL REFERENCES documents(id), user_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(document_id,user_id));
CREATE TABLE events (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, discord_id TEXT, channel_id TEXT NOT NULL, message_id TEXT, actor TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, location TEXT NOT NULL, starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, capacity INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'scheduled', reminder_sent INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE event_entries (event_id TEXT NOT NULL REFERENCES events(id), user_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(event_id,user_id));
CREATE TABLE locks (guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, previous TEXT NOT NULL, actor TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(guild_id,channel_id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, revision INTEGER NOT NULL, state TEXT NOT NULL, expires_at INTEGER NOT NULL);
